r"""
ALAS ONE-RUN QGIS FINAL PIPELINE

Gabungan tahap QGIS untuk Selat Alas:
1. Membuat raster halus awal dari CSV final georeferensi.
2. Membuat polygon grid aktif sebagai mask.
3. Memotong raster agar halus tetapi tidak kotak.

Jalankan dari QGIS Python Console:
exec(open(r"<PATH_KE_SCRIPT_INI>", encoding="utf-8").read())
"""

from pathlib import Path
import traceback

# =============================================================================
# CONFIG GITHUB — ISI PATH LOKAL DI SINI
# =============================================================================
# Script ini sengaja tidak menyimpan path komputer pribadi agar aman di GitHub.
#
# Cukup isi 2 path berikut saat menjalankan script di komputer sendiri.
# Contoh struktur folder:
#   D:\PROJECT\alas\qgis_export_final\
#   D:\PROJECT\alas\model\alass4.grd
#   D:\PROJECT\alas\model\alass4.dep
#   D:\PROJECT\alas\model\alass4.enc
#   D:\PROJECT\alas\model\alass4.bnd
#
# Jangan upload file data/model penelitian ke GitHub kecuali memang sengaja
# dipublikasikan.
QGIS_EXPORT_DIR = Path(r"")  # <-- ISI folder qgis_export_final
MODEL_DIR = Path(r"")        # <-- ISI folder model Delft3D

FAST_STAGE_CODE = '"""\n===============================================================================\nPIPELINE FINAL DELFT3D -> CSV GEOREFERENSI -> PETA QGIS (VERSI CEPAT)\nSTUDI KASUS: SELAT ALAS\n===============================================================================\n\nFungsi script\n-------------\n1. Membaca file grid Delft3D RGFGRID (*.grd).\n2. Memperbaiki kolom x/y pada CSV statistik arus berdasarkan indeks M dan N.\n3. Menyimpan CSV baru ke folder qgis_export_final tanpa menimpa CSV lama.\n4. Jika dijalankan dari QGIS Desktop, script sekaligus:\n   - membuat GeoPackage titik;\n   - membuat raster IDW GeoTIFF;\n   - memberi simbologi warna;\n   - menambahkan titik dominan;\n   - menyimpan project QGIS (*.qgz).\n\nCara menjalankan tahap 1 dari PowerShell\n----------------------------------------\npython <PATH_KE_SCRIPT_INI>\n\nCara menjalankan tahap 2 dari QGIS Desktop\n------------------------------------------\nQGIS -> Plugins -> Python Console, lalu jalankan:\nexec(open(r"<PATH_KE_SCRIPT_INI>", encoding="utf-8").read())\n\nCatatan\n-------\n- GRID_FILE (*.grd) wajib tersedia karena file tersebut menyimpan koordinat grid.\n- DEP_FILE, ENC_FILE, dan BND_FILE dicatat agar konfigurasi model lengkap, tetapi\n  tidak diperlukan untuk mengganti koordinat x/y.\n- Jika Coordinate System pada *.grd adalah Spherical, script memakai EPSG:4326.\n- Jika grid Cartesian, isi CARTESIAN_CRS secara manual sebelum membuat peta QGIS.\n===============================================================================\n"""\n\nfrom __future__ import annotations\n\nimport csv\nimport math\nimport re\nimport sys\nfrom pathlib import Path\nfrom typing import Iterable, Optional\n\n\n# =============================================================================\n# CONFIG — PATH MODEL ALAS\n# =============================================================================\n\nSELAT = "alas"\nSELAT_TITLE = "Selat Alas"\n\n# Folder CSV statistik yang sebelumnya dihasilkan dari trim-alas.dat.\nCSV_SOURCE_DIR = Path(r"__QGIS_EXPORT_DIR__")\n\n# Folder baru untuk CSV yang sudah memiliki koordinat sebenarnya dan hasil QGIS.\n# CSV awal tidak akan ditimpa.\nFINAL_DIR = Path(r"__QGIS_EXPORT_DIR__")\n\n# File input model Delft3D.\nGRID_FILE = Path(r"__MODEL_DIR__\\alass4.grd")\nDEP_FILE  = Path(r"__MODEL_DIR__\\alass4.dep")\nENC_FILE  = Path(r"__MODEL_DIR__\\alass4.enc")\nBND_FILE  = Path(r"__MODEL_DIR__\\alass4.bnd")\n\n# Untuk grid Cartesian, isi EPSG proyeksi model, misalnya "EPSG:32751".\n# Biarkan kosong jika file *.grd menggunakan Coordinate System = Spherical.\nCARTESIAN_CRS = ""\n\n# Pengaturan peta QGIS.\nADD_OSM_BASEMAP = False\nIDW_OUTPUT_WIDTH = 400\nIDW_POWER = 2.0\n# Radius pencarian dalam derajat karena grid Spherical (EPSG:4326).\n# 0.01 derajat kira-kira 1 km; cukup untuk mengambil tetangga terdekat.\nIDW_RADIUS = 0.01\nIDW_MAX_POINTS = 24\nIDW_MIN_POINTS = 1\nSTYLE_MAX_PERCENTILE = 98.0\nNODATA_VALUE = -9999.0\n\n# Layer yang dibuat dari alas_all_stats.csv.\nMAP_VARIABLES = {\n    "speed_mean": {\n        "title": "01 Kecepatan arus rata-rata",\n        "unit": "m/s",\n    },\n    "speed_spring": {\n        "title": "02 Kecepatan arus spring tide",\n        "unit": "m/s",\n    },\n    "speed_neap": {\n        "title": "03 Kecepatan arus neap tide",\n        "unit": "m/s",\n    },\n    "speed_p90": {\n        "title": "04 Kecepatan arus P90",\n        "unit": "m/s",\n    },\n    "power_mean": {\n        "title": "05 Densitas daya arus rata-rata",\n        "unit": "W/m²",\n    },\n    "prob_v075_pct": {\n        "title": "06 Probabilitas V ≥ 0,75 m/s",\n        "unit": "%",\n    },\n    "prob_v10_pct": {\n        "title": "07 Probabilitas V ≥ 1,00 m/s",\n        "unit": "%",\n    },\n}\n\nVISIBLE_LAYER_KEY = "speed_mean"\nLAYER_GROUP_NAME = "SELAT ALAS — PETA DELFT3D"\nDEFAULT_MISSING_VALUE = -999.0\nFLOAT_RE = re.compile(r"[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[EeDd][-+]?\\d+)?")\n\n\n# =============================================================================\n# STRUKTUR DATA\n# =============================================================================\n\nclass GridData:\n    """Container sederhana untuk grid Delft3D.\n\n    Kelas biasa dipakai agar kompatibel dengan Python Console QGIS yang\n    menjalankan script melalui exec() pada file sementara.\n    """\n\n    def __init__(\n        self,\n        path: Path,\n        coordinate_system: str,\n        missing_value: float,\n        mmax: int,\n        nmax: int,\n        x: list[list[float]],\n        y: list[list[float]],\n    ) -> None:\n        self.path = path\n        self.coordinate_system = coordinate_system\n        self.missing_value = missing_value\n        self.mmax = mmax\n        self.nmax = nmax\n        self.x = x\n        self.y = y\n\n\n# =============================================================================\n# UTILITAS UMUM\n# =============================================================================\n\ndef section(title: str) -> None:\n    print("\\n" + "=" * 78)\n    print(f"  {title}")\n    print("=" * 78)\n\n\ndef info(message: str) -> None:\n    print(f"  [OK] {message}")\n\n\ndef warning(message: str) -> None:\n    print(f"  [PERINGATAN] {message}")\n\n\ndef fail(message: str) -> None:\n    raise RuntimeError(message)\n\n\ndef parse_float(value: str) -> float:\n    return float(value.replace("D", "E").replace("d", "e"))\n\n\ndef numbers(text: str) -> list[float]:\n    return [parse_float(token) for token in FLOAT_RE.findall(text)]\n\n\ndef is_finite_number(value: float) -> bool:\n    return math.isfinite(value)\n\n\ndef is_valid_coordinate(value: float, missing_value: float) -> bool:\n    if not is_finite_number(value):\n        return False\n    if abs(value) > 1.0e20:\n        return False\n    tolerance = max(1.0e-8, abs(missing_value) * 1.0e-6)\n    if math.isclose(value, missing_value, abs_tol=tolerance):\n        return False\n    return True\n\n\ndef require_file(path: Path, label: str, required: bool = True) -> None:\n    if path.exists():\n        info(f"{label}: {path}")\n    elif required:\n        fail(f"{label} tidak ditemukan: {path}")\n    else:\n        warning(f"{label} tidak ditemukan, tetapi tidak diperlukan pada tahap ini: {path}")\n\n\n# =============================================================================\n# MEMBACA FILE GRID DELFT3D *.GRD\n# =============================================================================\n\ndef find_dimension_line(lines: list[str]) -> tuple[int, int, int]:\n    """Temukan baris dimensi MMAX NMAX pada file RGFGRID."""\n    for index, raw in enumerate(lines):\n        stripped = raw.strip()\n        if not stripped or stripped.startswith("*") or "=" in stripped:\n            continue\n        tokens = stripped.split()\n        if len(tokens) not in (2, 3):\n            continue\n        try:\n            ints = [int(token) for token in tokens]\n        except ValueError:\n            continue\n        if ints[0] > 1 and ints[1] > 1:\n            return index, ints[0], ints[1]\n    fail("Baris dimensi MMAX NMAX tidak ditemukan dalam file .grd.")\n\n\ndef collect_eta_rows(lines: list[str], start_index: int) -> list[tuple[int, list[float]]]:\n    """Kumpulkan blok ETA dari file RGFGRID. Satu ETA dapat memiliki baris sambungan."""\n    rows: list[tuple[int, list[float]]] = []\n    current_eta: Optional[int] = None\n    current_values: list[float] = []\n\n    def flush() -> None:\n        nonlocal current_eta, current_values\n        if current_eta is not None:\n            rows.append((current_eta, current_values))\n        current_eta = None\n        current_values = []\n\n    for raw in lines[start_index:]:\n        stripped = raw.strip()\n        if not stripped or stripped.startswith("*"):\n            continue\n\n        match = re.match(r"^ETA\\s*=\\s*([+-]?\\d+)\\s*(.*)$", stripped, flags=re.I)\n        if match:\n            flush()\n            current_eta = int(match.group(1))\n            current_values = numbers(match.group(2))\n            continue\n\n        if current_eta is not None:\n            current_values.extend(numbers(stripped))\n\n    flush()\n    return rows\n\n\ndef read_grd(path: Path) -> GridData:\n    text = path.read_text(encoding="utf-8", errors="ignore")\n    lines = text.splitlines()\n\n    coord_match = re.search(r"Coordinate\\s+System\\s*=\\s*([^\\r\\n]+)", text, flags=re.I)\n    coordinate_system = coord_match.group(1).strip() if coord_match else "Cartesian (default)"\n\n    miss_match = re.search(r"Missing\\s+Value\\s*=\\s*([^\\s\\r\\n]+)", text, flags=re.I)\n    try:\n        missing_value = parse_float(miss_match.group(1)) if miss_match else DEFAULT_MISSING_VALUE\n    except ValueError:\n        missing_value = DEFAULT_MISSING_VALUE\n\n    dimension_line, mmax, nmax = find_dimension_line(lines)\n    eta_rows = collect_eta_rows(lines, dimension_line + 1)\n\n    if len(eta_rows) < 2 * nmax:\n        fail(\n            "File .grd belum dapat dibaca sebagai format RGFGRID. "\n            f"Ditemukan {len(eta_rows)} blok ETA, tetapi minimal {2 * nmax} dibutuhkan "\n            f"untuk X dan Y. File: {path}"\n        )\n\n    x_rows = eta_rows[:nmax]\n    y_rows = eta_rows[nmax: 2 * nmax]\n\n    def build(rows: list[tuple[int, list[float]]], label: str) -> list[list[float]]:\n        output = [[math.nan for _ in range(mmax)] for _ in range(nmax)]\n        for fallback_row, (eta_index, vals) in enumerate(rows, start=1):\n            if len(vals) < mmax:\n                fail(\n                    f"Baris {label} ETA={eta_index} hanya memiliki {len(vals)} nilai; "\n                    f"dibutuhkan {mmax}."\n                )\n            row_number = eta_index if 1 <= eta_index <= nmax else fallback_row\n            output[row_number - 1] = vals[:mmax]\n        return output\n\n    x = build(x_rows, "X")\n    y = build(y_rows, "Y")\n\n    valid_pairs: list[tuple[float, float]] = []\n    for n_index in range(nmax):\n        for m_index in range(mmax):\n            xv = x[n_index][m_index]\n            yv = y[n_index][m_index]\n            if is_valid_coordinate(xv, missing_value) and is_valid_coordinate(yv, missing_value):\n                valid_pairs.append((xv, yv))\n\n    if not valid_pairs:\n        fail("Tidak ditemukan pasangan koordinat valid pada file .grd.")\n\n    x_values = [pair[0] for pair in valid_pairs]\n    y_values = [pair[1] for pair in valid_pairs]\n    if max(x_values) <= min(x_values) or max(y_values) <= min(y_values):\n        fail("Rentang koordinat file .grd tidak valid.")\n\n    return GridData(\n        path=path,\n        coordinate_system=coordinate_system,\n        missing_value=missing_value,\n        mmax=mmax,\n        nmax=nmax,\n        x=x,\n        y=y,\n    )\n\n\ndef grid_summary(grid: GridData) -> dict[str, float | int | str]:\n    x_values: list[float] = []\n    y_values: list[float] = []\n    for n_index in range(grid.nmax):\n        for m_index in range(grid.mmax):\n            xv = grid.x[n_index][m_index]\n            yv = grid.y[n_index][m_index]\n            if is_valid_coordinate(xv, grid.missing_value) and is_valid_coordinate(yv, grid.missing_value):\n                x_values.append(xv)\n                y_values.append(yv)\n\n    return {\n        "coordinate_system": grid.coordinate_system,\n        "missing_value": grid.missing_value,\n        "mmax": grid.mmax,\n        "nmax": grid.nmax,\n        "valid_points": len(x_values),\n        "xmin": min(x_values),\n        "xmax": max(x_values),\n        "ymin": min(y_values),\n        "ymax": max(y_values),\n    }\n\n\n# =============================================================================\n# MEMPERBAIKI KOORDINAT CSV\n# =============================================================================\n\ndef source_csv_files() -> list[Path]:\n    files = sorted(CSV_SOURCE_DIR.glob(f"{SELAT}_*.csv"))\n    files = [path for path in files if path.is_file()]\n    if not files:\n        fail(f"CSV dengan pola {SELAT}_*.csv tidak ditemukan pada: {CSV_SOURCE_DIR}")\n    return files\n\n\ndef repair_csv(source_path: Path, output_path: Path, grid: GridData) -> tuple[int, int]:\n    """Salin CSV dengan mengganti x/y berdasarkan M/N. Return jumlah simpan dan buang."""\n    with source_path.open("r", encoding="utf-8-sig", newline="") as source_file:\n        reader = csv.DictReader(source_file)\n        if reader.fieldnames is None:\n            fail(f"CSV tidak memiliki header: {source_path}")\n\n        fieldnames = list(reader.fieldnames)\n        if "M" not in fieldnames or "N" not in fieldnames:\n            warning(f"Lewati file tanpa kolom M/N: {source_path.name}")\n            return 0, 0\n\n        # Pastikan x/y ada dan ditempatkan setelah M/N.\n        fieldnames = [field for field in fieldnames if field not in {"x", "y"}]\n        insert_at = max(fieldnames.index("M"), fieldnames.index("N")) + 1\n        fieldnames[insert_at:insert_at] = ["x", "y"]\n\n        output_path.parent.mkdir(parents=True, exist_ok=True)\n        saved = 0\n        dropped = 0\n\n        with output_path.open("w", encoding="utf-8-sig", newline="") as output_file:\n            writer = csv.DictWriter(output_file, fieldnames=fieldnames)\n            writer.writeheader()\n\n            for line_number, row in enumerate(reader, start=2):\n                try:\n                    m = int(round(float(row["M"])))\n                    n = int(round(float(row["N"])))\n                except Exception as exc:\n                    fail(f"{source_path.name} baris {line_number}: nilai M/N tidak valid: {exc}")\n\n                if not (1 <= m <= grid.mmax and 1 <= n <= grid.nmax):\n                    fail(\n                        f"{source_path.name} baris {line_number}: M={m}, N={n} berada di luar "\n                        f"grid MMAX={grid.mmax}, NMAX={grid.nmax}. Periksa GRID_FILE."\n                    )\n\n                x = grid.x[n - 1][m - 1]\n                y = grid.y[n - 1][m - 1]\n                if not (\n                    is_valid_coordinate(x, grid.missing_value)\n                    and is_valid_coordinate(y, grid.missing_value)\n                ):\n                    dropped += 1\n                    continue\n\n                row["x"] = f"{x:.10f}"\n                row["y"] = f"{y:.10f}"\n                writer.writerow({field: row.get(field, "") for field in fieldnames})\n                saved += 1\n\n    return saved, dropped\n\n\ndef determine_crs(grid: GridData) -> str:\n    if "spher" in grid.coordinate_system.lower():\n        return "EPSG:4326"\n    if CARTESIAN_CRS.strip():\n        return CARTESIAN_CRS.strip()\n    return ""\n\n\ndef preprocess_csvs(grid: GridData) -> Path:\n    FINAL_DIR.mkdir(parents=True, exist_ok=True)\n    files = source_csv_files()\n\n    section("MEMPERBAIKI KOORDINAT CSV")\n    total_saved = 0\n    total_dropped = 0\n    processed = 0\n\n    for source_path in files:\n        output_path = FINAL_DIR / source_path.name\n        saved, dropped = repair_csv(source_path, output_path, grid)\n        if saved or dropped:\n            processed += 1\n            total_saved += saved\n            total_dropped += dropped\n            info(f"{output_path.name}: {saved} baris tersimpan; {dropped} baris kosong dibuang")\n\n    required_output = FINAL_DIR / f"{SELAT}_all_stats.csv"\n    if not required_output.exists():\n        fail(f"File wajib tidak terbentuk: {required_output}")\n\n    crs = determine_crs(grid)\n    summary = grid_summary(grid)\n    report_path = FINAL_DIR / f"{SELAT}_RINGKASAN_PIPELINE_FINAL.txt"\n    report_path.write_text(\n        "\\n".join([\n            f"PIPELINE FINAL DELFT3D -> QGIS — {SELAT.upper()}",\n            "=" * 78,\n            f"Grid file          : {GRID_FILE}",\n            f"DEP file           : {DEP_FILE}",\n            f"ENC file           : {ENC_FILE}",\n            f"BND file           : {BND_FILE}",\n            f"Coordinate System  : {summary[\'coordinate_system\']}",\n            f"CRS peta QGIS      : {crs or \'BELUM DIISI — grid Cartesian membutuhkan CARTESIAN_CRS\'}",\n            f"MMAX, NMAX         : {summary[\'mmax\']}, {summary[\'nmax\']}",\n            f"Titik grid valid   : {summary[\'valid_points\']}",\n            f"Rentang X          : {summary[\'xmin\']:.10f} s.d. {summary[\'xmax\']:.10f}",\n            f"Rentang Y          : {summary[\'ymin\']:.10f} s.d. {summary[\'ymax\']:.10f}",\n            f"CSV diproses       : {processed}",\n            f"Total baris simpan : {total_saved}",\n            f"Total baris buang  : {total_dropped}",\n            "",\n            "Tahap QGIS:",\n            "Jalankan file script yang sama melalui Python Console QGIS.",\n        ]),\n        encoding="utf-8",\n    )\n    info(f"Ringkasan tersimpan: {report_path}")\n    return required_output\n\n\n# =============================================================================\n# DETEKSI LINGKUNGAN QGIS\n# =============================================================================\n\ndef qgis_available() -> bool:\n    try:\n        import qgis.core  # noqa: F401\n        from osgeo import gdal  # noqa: F401\n        return True\n    except Exception:\n        return False\n\n\n# =============================================================================\n# PEMBUATAN PETA QGIS — HANYA DIEKSEKUSI DI DALAM QGIS DESKTOP\n# =============================================================================\n\ndef read_stats_rows(csv_path: Path) -> tuple[list[dict[str, float | int]], list[str]]:\n    required = {\n        "M", "N", "x", "y", "speed_mean", "speed_spring", "speed_neap",\n        "speed_p90", "power_mean", "prob_v075_pct", "prob_v10_pct",\n    }\n    rows: list[dict[str, float | int]] = []\n\n    with csv_path.open("r", encoding="utf-8-sig", newline="") as file:\n        reader = csv.DictReader(file)\n        if reader.fieldnames is None:\n            fail("alas_all_stats.csv tidak memiliki header.")\n        fieldnames = list(reader.fieldnames)\n        missing = sorted(required - set(fieldnames))\n        if missing:\n            fail(f"Kolom wajib tidak ditemukan: {\', \'.join(missing)}")\n\n        for line_number, raw in enumerate(reader, start=2):\n            row: dict[str, float | int] = {}\n            for field in fieldnames:\n                value = raw.get(field, "")\n                if value in (None, ""):\n                    continue\n                try:\n                    row[field] = int(round(float(value))) if field in {"M", "N"} else float(value)\n                except ValueError:\n                    fail(f"Nilai numerik tidak valid pada {csv_path.name} baris {line_number}, kolom {field}.")\n            rows.append(row)\n\n    if not rows:\n        fail("alas_all_stats.csv kosong.")\n    return rows, fieldnames\n\n\ndef create_qgis_project(stats_csv: Path, grid: GridData) -> None:\n    # Import sengaja dilakukan di dalam fungsi agar tahap CSV tetap bisa berjalan\n    # dari Python Windows biasa tanpa instalasi QGIS pada environment tersebut.\n    import numpy as np\n    from osgeo import gdal, ogr, osr\n    # Gunakan seluruh inti CPU bila didukung oleh versi GDAL pada QGIS.\n    gdal.SetConfigOption("GDAL_NUM_THREADS", "ALL_CPUS")\n    from qgis.PyQt.QtGui import QColor\n    from qgis.core import (\n        QgsColorRampShader,\n        QgsCoordinateReferenceSystem,\n        QgsMarkerSymbol,\n        QgsPalLayerSettings,\n        QgsProject,\n        QgsRasterLayer,\n        QgsRasterShader,\n        QgsSingleBandPseudoColorRenderer,\n        QgsTextBufferSettings,\n        QgsTextFormat,\n        QgsVectorLayer,\n        QgsVectorLayerSimpleLabeling,\n    )\n\n    crs_authid = determine_crs(grid)\n    if not crs_authid:\n        fail(\n            "Grid terdeteksi Cartesian, tetapi CARTESIAN_CRS masih kosong. "\n            "Isi CARTESIAN_CRS, misalnya EPSG zona UTM yang sesuai, lalu jalankan ulang di QGIS."\n        )\n\n    crs = QgsCoordinateReferenceSystem(crs_authid)\n    if not crs.isValid():\n        fail(f"CRS QGIS tidak valid: {crs_authid}")\n\n    output_dir = FINAL_DIR / "peta_qgis_final_cepat"\n    raster_dir = output_dir / "raster"\n    output_dir.mkdir(parents=True, exist_ok=True)\n    raster_dir.mkdir(parents=True, exist_ok=True)\n\n    rows, fieldnames = read_stats_rows(stats_csv)\n    numeric_fields = [field for field in fieldnames if field in rows[0]]\n\n    def remove_if_exists(path: Path) -> None:\n        if path.exists():\n            try:\n                path.unlink()\n            except PermissionError:\n                fail(f"Tidak dapat menimpa {path}. Tutup layer lama di QGIS, lalu jalankan ulang.")\n\n    def osr_from_crs():\n        srs = osr.SpatialReference()\n        if srs.ImportFromWkt(crs.toWkt()) != 0:\n            fail("CRS tidak dapat dikonversi ke format GDAL.")\n        return srs\n\n    # -------------------------------------------------------------------------\n    # Membuat GeoPackage titik\n    # -------------------------------------------------------------------------\n    gpkg_path = output_dir / f"{SELAT}_stats_points.gpkg"\n    remove_if_exists(gpkg_path)\n    driver = ogr.GetDriverByName("GPKG")\n    if driver is None:\n        fail("Driver GeoPackage GDAL tidak tersedia.")\n    datasource = driver.CreateDataSource(str(gpkg_path))\n    if datasource is None:\n        fail(f"Gagal membuat GeoPackage: {gpkg_path}")\n\n    layer_name = f"{SELAT}_stats"\n    ogr_layer = datasource.CreateLayer(layer_name, srs=osr_from_crs(), geom_type=ogr.wkbPoint)\n    if ogr_layer is None:\n        fail("Gagal membuat layer titik GeoPackage.")\n\n    for field in numeric_fields:\n        field_type = ogr.OFTInteger if field in {"M", "N"} else ogr.OFTReal\n        definition = ogr.FieldDefn(field, field_type)\n        if field_type == ogr.OFTReal:\n            definition.SetWidth(24)\n            definition.SetPrecision(10)\n        if ogr_layer.CreateField(definition) != 0:\n            fail(f"Gagal membuat field GeoPackage: {field}")\n\n    layer_definition = ogr_layer.GetLayerDefn()\n    for row in rows:\n        feature = ogr.Feature(layer_definition)\n        for field in numeric_fields:\n            if field in row:\n                feature.SetField(field, row[field])\n        geometry = ogr.Geometry(ogr.wkbPoint)\n        geometry.AddPoint(float(row["x"]), float(row["y"]))\n        feature.SetGeometry(geometry)\n        if ogr_layer.CreateFeature(feature) != 0:\n            fail("Gagal menulis salah satu titik ke GeoPackage.")\n        feature = None\n\n    ogr_layer.SyncToDisk()\n    datasource = None\n    info(f"GeoPackage titik dibuat: {gpkg_path}")\n\n    # -------------------------------------------------------------------------\n    # Membuat raster IDW\n    # -------------------------------------------------------------------------\n    x_values = np.asarray([float(row["x"]) for row in rows], dtype=float)\n    y_values = np.asarray([float(row["y"]) for row in rows], dtype=float)\n    xmin, xmax = float(np.nanmin(x_values)), float(np.nanmax(x_values))\n    ymin, ymax = float(np.nanmin(y_values)), float(np.nanmax(y_values))\n    if not (xmax > xmin and ymax > ymin):\n        fail("Rentang koordinat CSV tidak valid untuk interpolasi.")\n\n    xpad = max((xmax - xmin) * 0.01, 1.0e-12)\n    ypad = max((ymax - ymin) * 0.01, 1.0e-12)\n    bounds = [xmin - xpad, ymin - ypad, xmax + xpad, ymax + ypad]\n    aspect = (bounds[3] - bounds[1]) / (bounds[2] - bounds[0])\n    width = IDW_OUTPUT_WIDTH\n    height = max(100, min(2400, int(round(width * aspect))))\n\n    raster_paths: dict[str, Path] = {}\n    for field, config in MAP_VARIABLES.items():\n        raster_path = raster_dir / f"{SELAT}_{field}.tif"\n        remove_if_exists(raster_path)\n        info(f"Mulai raster {len(raster_paths) + 1}/{len(MAP_VARIABLES)}: {config[\'title\']}")\n        algorithm = (\n            f"invdistnn:power={IDW_POWER}:smoothing=0.0:radius={IDW_RADIUS}:"\n            f"max_points={IDW_MAX_POINTS}:min_points={IDW_MIN_POINTS}:nodata=-9999"\n        )\n        options = gdal.GridOptions(\n            format="GTiff",\n            outputType=gdal.GDT_Float32,\n            width=width,\n            height=height,\n            outputBounds=bounds,\n            outputSRS=crs.toWkt(),\n            algorithm=algorithm,\n            zfield=field,\n            noData=NODATA_VALUE,\n            creationOptions=["COMPRESS=LZW", "TILED=YES"],\n        )\n        dataset = gdal.Grid(str(raster_path), str(gpkg_path), options=options)\n        if dataset is None:\n            fail(f"GDAL IDW gagal membuat raster: {raster_path}")\n        dataset.FlushCache()\n        dataset = None\n        raster_paths[field] = raster_path\n        info(f"Raster dibuat: {config[\'title\']}")\n\n    # -------------------------------------------------------------------------\n    # Simbologi dan layer QGIS\n    # -------------------------------------------------------------------------\n    def style_raster(layer: QgsRasterLayer, values) -> None:\n        finite = values[np.isfinite(values)]\n        if finite.size == 0:\n            return\n        vmin = 0.0 if float(np.nanmin(finite)) >= 0 else float(np.nanpercentile(finite, 2))\n        vmax_full = float(np.nanmax(finite))\n        vmax = float(np.nanpercentile(finite, STYLE_MAX_PERCENTILE))\n        if not math.isfinite(vmax) or vmax <= vmin:\n            vmax = vmax_full\n        if vmax <= vmin:\n            vmax = vmin + 1.0\n\n        fractions = [0.00, 0.25, 0.50, 0.75, 1.00]\n        colors = [\n            QColor("#313695"), QColor("#74add1"), QColor("#ffffbf"),\n            QColor("#f46d43"), QColor("#a50026"),\n        ]\n        items = [\n            QgsColorRampShader.ColorRampItem(\n                vmin + fraction * (vmax - vmin), color,\n                f"{vmin + fraction * (vmax - vmin):.3f}",\n            )\n            for fraction, color in zip(fractions, colors)\n        ]\n        shader_function = QgsColorRampShader()\n        shader_function.setColorRampType(QgsColorRampShader.Interpolated)\n        shader_function.setColorRampItemList(items)\n        shader = QgsRasterShader()\n        shader.setRasterShaderFunction(shader_function)\n        renderer = QgsSingleBandPseudoColorRenderer(layer.dataProvider(), 1, shader)\n        try:\n            renderer.setClassificationMin(vmin)\n            renderer.setClassificationMax(vmax)\n        except Exception:\n            pass\n        layer.setRenderer(renderer)\n        layer.triggerRepaint()\n\n    project = QgsProject.instance()\n    project.setCrs(crs)\n    root = project.layerTreeRoot()\n    previous_group = root.findGroup(LAYER_GROUP_NAME)\n    if previous_group is not None:\n        previous_layer_ids = [node.layerId() for node in previous_group.findLayers()]\n        root.removeChildNode(previous_group)\n        for layer_id in previous_layer_ids:\n            project.removeMapLayer(layer_id)\n\n    group = root.insertGroup(0, LAYER_GROUP_NAME)\n    raster_layers = {}\n    for field, config in MAP_VARIABLES.items():\n        raster_layer = QgsRasterLayer(str(raster_paths[field]), f"{config[\'title\']} [{config[\'unit\']}]", "gdal")\n        if not raster_layer.isValid():\n            fail(f"Raster gagal dimuat ke QGIS: {raster_paths[field]}")\n        values = np.asarray([float(row[field]) for row in rows], dtype=float)\n        style_raster(raster_layer, values)\n        project.addMapLayer(raster_layer, False)\n        node = group.addLayer(raster_layer)\n        node.setItemVisibilityChecked(field == VISIBLE_LAYER_KEY)\n        raster_layers[field] = raster_layer\n\n    points_uri = f"{gpkg_path}|layername={layer_name}"\n    points_layer = QgsVectorLayer(points_uri, "08 Titik statistik lengkap", "ogr")\n    if not points_layer.isValid():\n        fail("Layer titik GeoPackage gagal dimuat.")\n    project.addMapLayer(points_layer, False)\n    group.addLayer(points_layer).setItemVisibilityChecked(False)\n\n    dominant = max(rows, key=lambda row: float(row["speed_mean"]))\n    dominant_layer = QgsVectorLayer(points_uri, "09 Titik dominan speed mean", "ogr")\n    dominant_layer.setSubsetString(f\'"M" = {int(dominant["M"])} AND "N" = {int(dominant["N"])}\')\n    symbol = QgsMarkerSymbol.createSimple({\n        "name": "star",\n        "color": "255,0,0,255",\n        "outline_color": "255,255,255,255",\n        "outline_width": "0.8",\n        "size": "5.5",\n    })\n    dominant_layer.renderer().setSymbol(symbol)\n\n    label_settings = QgsPalLayerSettings()\n    label_settings.enabled = True\n    label_settings.isExpression = True\n    label_settings.fieldName = "\'Titik dominan\'"\n    text_format = QgsTextFormat()\n    text_format.setSize(10)\n    text_format.setColor(QColor("#111111"))\n    buffer = QgsTextBufferSettings()\n    buffer.setEnabled(True)\n    buffer.setSize(1.0)\n    buffer.setColor(QColor("#ffffff"))\n    text_format.setBuffer(buffer)\n    label_settings.setFormat(text_format)\n    dominant_layer.setLabelsEnabled(True)\n    dominant_layer.setLabeling(QgsVectorLayerSimpleLabeling(label_settings))\n\n    project.addMapLayer(dominant_layer, False)\n    group.addLayer(dominant_layer).setItemVisibilityChecked(True)\n\n    if ADD_OSM_BASEMAP and crs_authid == "EPSG:4326":\n        osm_uri = "type=xyz&url=https://tile.openstreetmap.org/{z}/{x}/{y}.png&zmin=0&zmax=19"\n        osm = QgsRasterLayer(osm_uri, "OpenStreetMap", "wms")\n        if osm.isValid():\n            project.addMapLayer(osm, True)\n        else:\n            warning("Basemap OpenStreetMap gagal dimuat. Periksa koneksi internet.")\n\n    project_path = output_dir / f"{SELAT}_peta_qgis_final.qgz"\n    if not project.write(str(project_path)):\n        fail(f"Project QGIS gagal disimpan: {project_path}")\n\n    try:\n        iface.mapCanvas().setExtent(raster_layers[VISIBLE_LAYER_KEY].extent())\n        iface.mapCanvas().refresh()\n    except Exception:\n        warning("Canvas QGIS tidak dapat di-zoom otomatis, tetapi layer berhasil dibuat.")\n\n    section("PETA QGIS SELESAI")\n    info(f"Project QGIS: {project_path}")\n    info(f"GeoPackage titik: {gpkg_path}")\n    info(f"Titik dominan M/N: {int(dominant[\'M\'])}, {int(dominant[\'N\'])}")\n    info(f"Titik dominan x/y: {float(dominant[\'x\']):.10f}, {float(dominant[\'y\']):.10f}")\n    info(f"Speed mean dominan: {float(dominant[\'speed_mean\']):.4f} m/s")\n    info(f"Power mean dominan: {float(dominant[\'power_mean\']):.2f} W/m²")\n\n\n# =============================================================================\n# MAIN\n# =============================================================================\n\ndef main() -> None:\n    section("PIPELINE FINAL DELFT3D -> QGIS — SELAT ALAS")\n\n    require_file(GRID_FILE, "GRID_FILE (.grd)", required=True)\n    require_file(DEP_FILE, "DEP_FILE (.dep)", required=False)\n    require_file(ENC_FILE, "ENC_FILE (.enc)", required=False)\n    require_file(BND_FILE, "BND_FILE (.bnd)", required=False)\n    FINAL_DIR.mkdir(parents=True, exist_ok=True)\n    info(f"Folder CSV final georeferensi: {FINAL_DIR}")\n\n    section("MEMBACA KOORDINAT GRID DELFT3D")\n    grid = read_grd(GRID_FILE)\n    summary = grid_summary(grid)\n    info(f"Coordinate System: {summary[\'coordinate_system\']}")\n    info(f"MMAX, NMAX: {summary[\'mmax\']}, {summary[\'nmax\']}")\n    info(f"Titik grid valid: {summary[\'valid_points\']}")\n    info(f"Rentang X: {summary[\'xmin\']:.10f} s.d. {summary[\'xmax\']:.10f}")\n    info(f"Rentang Y: {summary[\'ymin\']:.10f} s.d. {summary[\'ymax\']:.10f}")\n\n    stats_csv = FINAL_DIR / f"{SELAT}_all_stats.csv"\n    require_file(stats_csv, "CSV final georeferensi")\n\n    section("STATUS LINGKUNGAN")\n    if qgis_available():\n        info("Lingkungan QGIS terdeteksi. Pembuatan layer dan raster dilanjutkan.")\n        create_qgis_project(stats_csv, grid)\n    else:\n        info("Tahap koreksi koordinat CSV selesai dijalankan dari Python Windows.")\n        print(f"  Folder hasil CSV georeferensi: {FINAL_DIR}")\n        print("\\n  Untuk membuat peta secara otomatis, buka QGIS Desktop -> Plugins -> Python Console")\n        print("  kemudian jalankan satu baris berikut:")\n        print(f\'  exec(open(r"{Path(__file__).resolve()}", encoding="utf-8").read())\')\n\n\nif __name__ in {"__main__", "builtins"}:\n    try:\n        main()\n    except Exception as exc:\n        print("\\n" + "!" * 78)\n        print(f"ERROR: {exc}")\n        print("!" * 78)\n        if __name__ == "__main__":\n            sys.exit(1)\n        raise\n'

POLYGON_STAGE_CODE = '"""\n===============================================================================\nSELAT ALAS — POLYGON GRID AKTIF DELFT3D UNTUK QGIS\n===============================================================================\nTujuan\n------\nMembuat peta polygon grid aktif dari grid Delft3D (*.grd) dan statistik arus\nCSV yang sudah memiliki koordinat geografis. Setiap baris aktif M/N menjadi\nsatu polygon sel grid. Tidak ada interpolasi IDW, sehingga bentuk domain tidak\nmelebar menjadi persegi panjang.\n\nCara menjalankan di QGIS Desktop\n--------------------------------\nQGIS -> Plugins -> Python Console -> Show Editor -> buka script ini -> Run.\nAtau tempel di Python Console:\nexec(open(r"<PATH_KE_SCRIPT_INI>", encoding="utf-8").read())\n\nCatatan\n-------\n- Script memakai alas_all_stats.csv dari qgis_export_final.\n- Polygon dibangun dari empat titik grid bertetangga pada file *.grd.\n- Baris statistik yang berada tepat pada batas grid dan tidak memiliki empat\n  titik sudut lengkap akan dilewati.\n===============================================================================\n"""\n\nfrom __future__ import annotations\n\nimport csv\nimport math\nimport re\nfrom pathlib import Path\nfrom typing import Optional\n\n\n# =============================================================================\n# CONFIG\n# =============================================================================\n\nSELAT = "alas"\nGRID_FILE = Path(r"__MODEL_DIR__\\alass4.grd")\nSTATS_CSV = Path(r"__QGIS_EXPORT_DIR__\\alas_all_stats.csv")\nOUTPUT_DIR = Path(r"__QGIS_EXPORT_DIR__\\peta_polygon_grid_aktif")\nGPKG_FILE = OUTPUT_DIR / "alas_grid_aktif.gpkg"\nPROJECT_FILE = OUTPUT_DIR / "alas_polygon_grid_aktif.qgz"\nLAYER_NAME = "alas_grid_aktif"\nGROUP_NAME = "SELAT ALAS — POLYGON GRID AKTIF"\nCRS_AUTHID = "EPSG:4326"\n\n# Jika polygon terlihat bergeser satu sel, ubah nilai ini menjadi -1 atau 1.\n# Untuk konfigurasi model Alas saat ini, mulai dengan 0.\nCELL_OFFSET_M = 0\nCELL_OFFSET_N = 0\n\n# Transparansi polygon agar citra satelit masih terlihat.\nPOLYGON_OPACITY = 0.72\n\n# Legenda tetap untuk seluruh peta kecepatan [m/s].\nSPEED_BREAKS = [0.00, 0.40, 0.75, 1.00, 1.25, 1.50]\nPROB_BREAKS = [0.0, 20.0, 40.0, 60.0, 80.0, 100.0]\n\n# File *.grd Delft3D biasanya menggunakan -999 sebagai missing value.\nDEFAULT_MISSING_VALUE = -999.0\nFLOAT_RE = re.compile(r"[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[EeDd][-+]?\\d+)?")\n\nMAP_VARIABLES = {\n    "speed_mean": {\n        "title": "01 Grid aktif — Kecepatan arus rata-rata [m/s]",\n        "kind": "speed",\n    },\n    "speed_spring": {\n        "title": "02 Grid aktif — Kecepatan arus spring tide [m/s]",\n        "kind": "speed",\n    },\n    "speed_neap": {\n        "title": "03 Grid aktif — Kecepatan arus neap tide [m/s]",\n        "kind": "speed",\n    },\n    "speed_p90": {\n        "title": "04 Grid aktif — Kecepatan arus P90 [m/s]",\n        "kind": "speed",\n    },\n    "power_mean": {\n        "title": "05 Grid aktif — Densitas daya rata-rata [W/m²]",\n        "kind": "power",\n    },\n    "prob_v075_pct": {\n        "title": "06 Grid aktif — Probabilitas V ≥ 0,75 m/s [%]",\n        "kind": "probability",\n    },\n    "prob_v10_pct": {\n        "title": "07 Grid aktif — Probabilitas V ≥ 1,00 m/s [%]",\n        "kind": "probability",\n    },\n}\nVISIBLE_FIELD = "speed_mean"\n\n\n# =============================================================================\n# UTILITAS\n# =============================================================================\n\n\ndef section(title: str) -> None:\n    print("\\n" + "=" * 78)\n    print(f"  {title}")\n    print("=" * 78)\n\n\ndef info(message: str) -> None:\n    print(f"  [OK] {message}")\n\n\ndef warning(message: str) -> None:\n    print(f"  [PERINGATAN] {message}")\n\n\ndef fail(message: str) -> None:\n    raise RuntimeError(message)\n\n\ndef parse_float(value: str) -> float:\n    return float(value.replace("D", "E").replace("d", "e"))\n\n\ndef numbers(text: str) -> list[float]:\n    return [parse_float(token) for token in FLOAT_RE.findall(text)]\n\n\ndef is_valid_coordinate(value: float, missing_value: float) -> bool:\n    if not math.isfinite(value):\n        return False\n    if abs(value) > 1.0e20:\n        return False\n    tolerance = max(1.0e-8, abs(missing_value) * 1.0e-6)\n    if math.isclose(value, missing_value, abs_tol=tolerance):\n        return False\n    return True\n\n\n# =============================================================================\n# MEMBACA GRID RGFGRID *.GRD\n# =============================================================================\n\n\nclass GridData:\n    def __init__(\n        self,\n        coordinate_system: str,\n        missing_value: float,\n        mmax: int,\n        nmax: int,\n        x: list[list[float]],\n        y: list[list[float]],\n    ) -> None:\n        self.coordinate_system = coordinate_system\n        self.missing_value = missing_value\n        self.mmax = mmax\n        self.nmax = nmax\n        self.x = x\n        self.y = y\n\n\ndef find_dimension_line(lines: list[str]) -> tuple[int, int, int]:\n    for index, raw in enumerate(lines):\n        stripped = raw.strip()\n        if not stripped or stripped.startswith("*") or "=" in stripped:\n            continue\n        tokens = stripped.split()\n        if len(tokens) not in (2, 3):\n            continue\n        try:\n            ints = [int(token) for token in tokens]\n        except ValueError:\n            continue\n        if ints[0] > 1 and ints[1] > 1:\n            return index, ints[0], ints[1]\n    fail("Baris dimensi MMAX NMAX tidak ditemukan dalam file .grd.")\n\n\ndef collect_eta_rows(lines: list[str], start_index: int) -> list[tuple[int, list[float]]]:\n    rows: list[tuple[int, list[float]]] = []\n    current_eta: Optional[int] = None\n    current_values: list[float] = []\n\n    def flush() -> None:\n        nonlocal current_eta, current_values\n        if current_eta is not None:\n            rows.append((current_eta, current_values))\n        current_eta = None\n        current_values = []\n\n    for raw in lines[start_index:]:\n        stripped = raw.strip()\n        if not stripped or stripped.startswith("*"):\n            continue\n        match = re.match(r"^ETA\\s*=\\s*([+-]?\\d+)\\s*(.*)$", stripped, flags=re.I)\n        if match:\n            flush()\n            current_eta = int(match.group(1))\n            current_values = numbers(match.group(2))\n            continue\n        if current_eta is not None:\n            current_values.extend(numbers(stripped))\n    flush()\n    return rows\n\n\ndef read_grd(path: Path) -> GridData:\n    if not path.exists():\n        fail(f"File grid tidak ditemukan: {path}")\n\n    text = path.read_text(encoding="utf-8", errors="ignore")\n    lines = text.splitlines()\n\n    coord_match = re.search(r"Coordinate\\s+System\\s*=\\s*([^\\r\\n]+)", text, flags=re.I)\n    coordinate_system = coord_match.group(1).strip() if coord_match else "Cartesian (default)"\n\n    miss_match = re.search(r"Missing\\s+Value\\s*=\\s*([^\\s\\r\\n]+)", text, flags=re.I)\n    try:\n        missing_value = parse_float(miss_match.group(1)) if miss_match else DEFAULT_MISSING_VALUE\n    except ValueError:\n        missing_value = DEFAULT_MISSING_VALUE\n\n    dimension_line, mmax, nmax = find_dimension_line(lines)\n    eta_rows = collect_eta_rows(lines, dimension_line + 1)\n    if len(eta_rows) < 2 * nmax:\n        fail(\n            f"Format .grd belum berhasil dibaca. Ditemukan {len(eta_rows)} blok ETA, "\n            f"tetapi minimal {2 * nmax} dibutuhkan."\n        )\n\n    def build(rows: list[tuple[int, list[float]]], label: str) -> list[list[float]]:\n        output = [[math.nan for _ in range(mmax)] for _ in range(nmax)]\n        for fallback_row, (eta_index, vals) in enumerate(rows, start=1):\n            if len(vals) < mmax:\n                fail(f"Baris {label} ETA={eta_index} hanya memiliki {len(vals)} nilai; dibutuhkan {mmax}.")\n            row_number = eta_index if 1 <= eta_index <= nmax else fallback_row\n            output[row_number - 1] = vals[:mmax]\n        return output\n\n    x = build(eta_rows[:nmax], "X")\n    y = build(eta_rows[nmax: 2 * nmax], "Y")\n    return GridData(coordinate_system, missing_value, mmax, nmax, x, y)\n\n\n# =============================================================================\n# MEMBACA CSV STATISTIK\n# =============================================================================\n\n\ndef read_stats(path: Path) -> tuple[list[dict[str, float | int]], list[str]]:\n    if not path.exists():\n        fail(f"CSV statistik tidak ditemukan: {path}")\n\n    rows: list[dict[str, float | int]] = []\n    with path.open("r", encoding="utf-8-sig", newline="") as handle:\n        reader = csv.DictReader(handle)\n        if reader.fieldnames is None:\n            fail("CSV tidak memiliki header.")\n        fieldnames = list(reader.fieldnames)\n        required = {"M", "N", "x", "y", *MAP_VARIABLES.keys()}\n        missing = sorted(required.difference(fieldnames))\n        if missing:\n            fail(f"Kolom wajib tidak tersedia pada CSV: {missing}")\n\n        for line_number, raw in enumerate(reader, start=2):\n            row: dict[str, float | int] = {}\n            try:\n                for field in fieldnames:\n                    if raw.get(field, "") == "":\n                        continue\n                    row[field] = int(round(float(raw[field]))) if field in {"M", "N"} else float(raw[field])\n            except Exception as exc:\n                fail(f"CSV baris {line_number} memiliki nilai tidak valid: {exc}")\n            rows.append(row)\n\n    if not rows:\n        fail("CSV statistik kosong.")\n    return rows, fieldnames\n\n\n# =============================================================================\n# MEMBENTUK POLYGON GRID AKTIF\n# =============================================================================\n\n\ndef get_cell_ring(grid: GridData, m: int, n: int) -> Optional[list[tuple[float, float]]]:\n    """Ambil empat sudut polygon untuk sel aktif M/N.\n\n    Indeks CSV M/N dimulai dari 1. Polygon menggunakan empat titik grid:\n    (M,N), (M+1,N), (M+1,N+1), (M,N+1).\n    """\n    m0 = (m - 1) + CELL_OFFSET_M\n    n0 = (n - 1) + CELL_OFFSET_N\n    corners = [(m0, n0), (m0 + 1, n0), (m0 + 1, n0 + 1), (m0, n0 + 1)]\n\n    points: list[tuple[float, float]] = []\n    for mi, ni in corners:\n        if not (0 <= mi < grid.mmax and 0 <= ni < grid.nmax):\n            return None\n        xv = grid.x[ni][mi]\n        yv = grid.y[ni][mi]\n        if not (is_valid_coordinate(xv, grid.missing_value) and is_valid_coordinate(yv, grid.missing_value)):\n            return None\n        points.append((float(xv), float(yv)))\n\n    # Hindari polygon degeneratif.\n    if len(set(points)) < 3:\n        return None\n    points.append(points[0])\n    return points\n\n\ndef remove_existing_gpkg(path: Path) -> None:\n    if not path.exists():\n        return\n    try:\n        path.unlink()\n    except PermissionError:\n        fail(\n            f"Tidak dapat menimpa {path}. Tutup project atau hapus layer polygon lama dari QGIS, "\n            "kemudian jalankan ulang script."\n        )\n\n\ndef create_polygon_gpkg(grid: GridData, rows: list[dict[str, float | int]], fieldnames: list[str]) -> tuple[int, int]:\n    from osgeo import ogr, osr\n\n    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)\n    remove_existing_gpkg(GPKG_FILE)\n\n    driver = ogr.GetDriverByName("GPKG")\n    if driver is None:\n        fail("Driver GeoPackage tidak tersedia pada instalasi GDAL QGIS.")\n    datasource = driver.CreateDataSource(str(GPKG_FILE))\n    if datasource is None:\n        fail(f"GeoPackage gagal dibuat: {GPKG_FILE}")\n\n    srs = osr.SpatialReference()\n    if srs.SetFromUserInput(CRS_AUTHID) != 0:\n        fail(f"CRS tidak valid: {CRS_AUTHID}")\n\n    layer = datasource.CreateLayer(LAYER_NAME, srs=srs, geom_type=ogr.wkbPolygon)\n    if layer is None:\n        fail("Layer polygon gagal dibuat.")\n\n    # Simpan semua statistik numerik agar satu GeoPackage dapat dipakai untuk seluruh peta.\n    numeric_fields = [field for field in fieldnames if field in rows[0]]\n    for field in numeric_fields:\n        ogr_type = ogr.OFTInteger if field in {"M", "N"} else ogr.OFTReal\n        definition = ogr.FieldDefn(field, ogr_type)\n        if ogr_type == ogr.OFTReal:\n            definition.SetWidth(24)\n            definition.SetPrecision(10)\n        if layer.CreateField(definition) != 0:\n            fail(f"Gagal membuat field: {field}")\n\n    saved = 0\n    skipped = 0\n    layer_defn = layer.GetLayerDefn()\n\n    for row in rows:\n        m = int(row["M"])\n        n = int(row["N"])\n        ring_points = get_cell_ring(grid, m, n)\n        if ring_points is None:\n            skipped += 1\n            continue\n\n        ring = ogr.Geometry(ogr.wkbLinearRing)\n        for x, y in ring_points:\n            ring.AddPoint(x, y)\n        polygon = ogr.Geometry(ogr.wkbPolygon)\n        polygon.AddGeometry(ring)\n\n        # Abaikan polygon dengan luas nol.\n        if abs(polygon.GetArea()) <= 1.0e-18:\n            skipped += 1\n            continue\n\n        feature = ogr.Feature(layer_defn)\n        for field in numeric_fields:\n            if field in row:\n                feature.SetField(field, row[field])\n        feature.SetGeometry(polygon)\n        if layer.CreateFeature(feature) != 0:\n            fail(f"Gagal menulis polygon M={m}, N={n}.")\n        feature = None\n        saved += 1\n\n    layer.SyncToDisk()\n    datasource = None\n    return saved, skipped\n\n\n# =============================================================================\n# MEMUAT DAN MEMBERI WARNA DI QGIS\n# =============================================================================\n\n\ndef create_qgis_layers(rows: list[dict[str, float | int]]) -> None:\n    from qgis.PyQt.QtGui import QColor\n    from qgis.core import (\n        QgsFillSymbol,\n        QgsGraduatedSymbolRenderer,\n        QgsMarkerSymbol,\n        QgsPalLayerSettings,\n        QgsProject,\n        QgsRendererRange,\n        QgsTextBufferSettings,\n        QgsTextFormat,\n        QgsVectorLayer,\n        QgsVectorLayerSimpleLabeling,\n    )\n\n    project = QgsProject.instance()\n    root = project.layerTreeRoot()\n\n    previous_group = root.findGroup(GROUP_NAME)\n    if previous_group is not None:\n        old_ids = [node.layerId() for node in previous_group.findLayers()]\n        root.removeChildNode(previous_group)\n        for layer_id in old_ids:\n            project.removeMapLayer(layer_id)\n\n    group = root.insertGroup(0, GROUP_NAME)\n    uri = f"{GPKG_FILE}|layername={LAYER_NAME}"\n\n    colors = [\n        QColor("#313695"),\n        QColor("#74add1"),\n        QColor("#ffffbf"),\n        QColor("#f46d43"),\n        QColor("#a50026"),\n    ]\n\n    def make_renderer(field: str, kind: str):\n        values = [float(row[field]) for row in rows if field in row and math.isfinite(float(row[field]))]\n        if not values:\n            fail(f"Tidak ada nilai valid untuk field {field}.")\n\n        if kind == "speed":\n            breaks = SPEED_BREAKS\n        elif kind == "probability":\n            breaks = PROB_BREAKS\n        else:\n            # Power memakai interval berdasarkan rentang data agar legenda tetap terbaca.\n            vmin = 0.0 if min(values) >= 0 else min(values)\n            vmax = max(values)\n            if vmax <= vmin:\n                vmax = vmin + 1.0\n            step = (vmax - vmin) / 5.0\n            breaks = [vmin + i * step for i in range(6)]\n\n        ranges = []\n        for index in range(5):\n            lower = float(breaks[index])\n            upper = float(breaks[index + 1])\n            symbol = QgsFillSymbol.createSimple({\n                "color": colors[index].name(),\n                "outline_color": "70,70,70,90",\n                "outline_width": "0.05",\n            })\n            symbol.setOpacity(POLYGON_OPACITY)\n            if kind == "probability":\n                label = f"{lower:.0f}–{upper:.0f} %"\n            elif kind == "power":\n                label = f"{lower:.0f}–{upper:.0f} W/m²"\n            else:\n                label = f"{lower:.2f}–{upper:.2f} m/s"\n            ranges.append(QgsRendererRange(lower, upper, symbol, label))\n        return QgsGraduatedSymbolRenderer(field, ranges)\n\n    polygon_layers = {}\n    for field, config in MAP_VARIABLES.items():\n        layer = QgsVectorLayer(uri, config["title"], "ogr")\n        if not layer.isValid():\n            fail(f"Layer polygon gagal dimuat untuk field: {field}")\n        layer.setRenderer(make_renderer(field, config["kind"]))\n        project.addMapLayer(layer, False)\n        node = group.addLayer(layer)\n        node.setItemVisibilityChecked(field == VISIBLE_FIELD)\n        polygon_layers[field] = layer\n\n    # Titik dominan ditempatkan pada centroid polygon dengan speed_mean maksimum.\n    dominant = max(rows, key=lambda row: float(row["speed_mean"]))\n    dominant_m = int(dominant["M"])\n    dominant_n = int(dominant["N"])\n\n    dominant_layer = QgsVectorLayer(f"Point?crs={CRS_AUTHID}", "08 Titik dominan", "memory")\n    provider = dominant_layer.dataProvider()\n\n    from qgis.core import QgsFeature, QgsField, QgsGeometry, QgsPointXY\n    from qgis.PyQt.QtCore import QVariant\n\n    provider.addAttributes([\n        QgsField("M", QVariant.Int),\n        QgsField("N", QVariant.Int),\n        QgsField("speed_mean", QVariant.Double),\n    ])\n    dominant_layer.updateFields()\n\n    ring = get_cell_ring(GLOBAL_GRID, dominant_m, dominant_n)\n    if ring is not None:\n        # Centroid sederhana dari empat titik sudut tanpa titik penutup.\n        x = sum(point[0] for point in ring[:-1]) / 4.0\n        y = sum(point[1] for point in ring[:-1]) / 4.0\n    else:\n        x = float(dominant["x"])\n        y = float(dominant["y"])\n\n    feat = QgsFeature(dominant_layer.fields())\n    feat.setGeometry(QgsGeometry.fromPointXY(QgsPointXY(x, y)))\n    feat.setAttributes([dominant_m, dominant_n, float(dominant["speed_mean"])])\n    provider.addFeature(feat)\n\n    symbol = QgsMarkerSymbol.createSimple({\n        "name": "star",\n        "color": "255,0,0,255",\n        "outline_color": "255,255,255,255",\n        "outline_width": "0.8",\n        "size": "5.5",\n    })\n    dominant_layer.renderer().setSymbol(symbol)\n\n    label_settings = QgsPalLayerSettings()\n    label_settings.enabled = True\n    label_settings.isExpression = True\n    label_settings.fieldName = "\'Titik dominan\'"\n    text_format = QgsTextFormat()\n    text_format.setSize(10)\n    buffer = QgsTextBufferSettings()\n    buffer.setEnabled(True)\n    buffer.setSize(1.2)\n    buffer.setColor(QColor("white"))\n    text_format.setBuffer(buffer)\n    label_settings.setFormat(text_format)\n    dominant_layer.setLabelsEnabled(True)\n    dominant_layer.setLabeling(QgsVectorLayerSimpleLabeling(label_settings))\n\n    project.addMapLayer(dominant_layer, False)\n    group.addLayer(dominant_layer).setItemVisibilityChecked(True)\n\n    project.setCrs(polygon_layers[VISIBLE_FIELD].crs())\n    polygon_layers[VISIBLE_FIELD].removeSelection()\n\n    # Zoom ke domain polygon aktif.\n    extent = polygon_layers[VISIBLE_FIELD].extent()\n    iface.mapCanvas().setExtent(extent)\n    iface.mapCanvas().refresh()\n\n    if not project.write(str(PROJECT_FILE)):\n        warning(f"Project belum dapat disimpan otomatis: {PROJECT_FILE}")\n    else:\n        info(f"Project QGIS tersimpan: {PROJECT_FILE}")\n\n    info(f"Titik dominan M/N: {dominant_m}, {dominant_n}")\n    info(f"Titik dominan centroid x/y: {x:.10f}, {y:.10f}")\n    info(f"Speed mean dominan: {float(dominant[\'speed_mean\']):.4f} m/s")\n\n\n# =============================================================================\n# MAIN\n# =============================================================================\n\n\nGLOBAL_GRID: GridData\n\n\ndef main() -> None:\n    global GLOBAL_GRID\n\n    section("POLYGON GRID AKTIF DELFT3D -> QGIS — SELAT ALAS")\n    info(f"GRID_FILE: {GRID_FILE}")\n    info(f"STATS_CSV: {STATS_CSV}")\n\n    section("MEMBACA GRID DELFT3D")\n    GLOBAL_GRID = read_grd(GRID_FILE)\n    info(f"Coordinate System: {GLOBAL_GRID.coordinate_system}")\n    info(f"MMAX, NMAX: {GLOBAL_GRID.mmax}, {GLOBAL_GRID.nmax}")\n\n    if "spher" not in GLOBAL_GRID.coordinate_system.lower():\n        warning(\n            "Grid bukan Spherical. Periksa CRS_AUTHID sebelum memakai layer sebagai peta final."\n        )\n\n    section("MEMBACA CSV STATISTIK")\n    rows, fieldnames = read_stats(STATS_CSV)\n    info(f"Jumlah baris statistik: {len(rows)}")\n\n    section("MEMBUAT GEOPACKAGE POLYGON GRID AKTIF")\n    saved, skipped = create_polygon_gpkg(GLOBAL_GRID, rows, fieldnames)\n    info(f"Polygon tersimpan: {saved}")\n    info(f"Polygon dilewati karena sudut tidak lengkap / invalid: {skipped}")\n    info(f"GeoPackage: {GPKG_FILE}")\n\n    section("SKIP PEMUATAN POLYGON KE QGIS")\n    info("GeoPackage polygon mask sudah dibuat. Tahap QGIS layer polygon dilewati agar tidak error pada versi QGIS tertentu.")\n    info("Polygon tetap dipakai sebagai mask untuk memotong raster final.")\n\n    section("SELESAI")\n    info("Polygon grid aktif selesai dibuat sebagai mask domain model.")\n\n\n# Sengaja dipanggil langsung agar berjalan dari QGIS Python Console maupun Editor.\nmain()\n'

MASK_STAGE_CODE = '"""\n===============================================================================\nSELAT ALAS — RASTER HALUS TERPOTONG MASK GRID AKTIF (FINAL)\n===============================================================================\nTujuan\n------\nMembuat peta raster halus seperti hasil IDW sebelumnya, tetapi memotong raster\nmengikuti domain polygon grid aktif Delft3D. Dengan demikian, raster tidak lagi\nmelebar menjadi persegi panjang di luar domain model.\n\nLegenda kecepatan\n-----------------\nEmpat layer kecepatan menggunakan legenda yang sama: 0,00 sampai 1,50 m/s.\nNilai raster asli TIDAK diubah. Nilai yang melebihi 1,50 m/s tetap tersimpan\npada GeoTIFF dan ditampilkan menggunakan warna kelas tertinggi.\n\nPrasyarat\n---------\n1. Raster IDW versi cepat sudah tersedia pada folder peta_qgis_final_cepat.\n2. Polygon grid aktif sudah dibuat dengan alas_qgis_polygon_grid_aktif.py.\n\nCara menjalankan di QGIS Desktop\n--------------------------------\nQGIS -> Plugins -> Python Console, kemudian jalankan:\nexec(open(r"<PATH_KE_SCRIPT_INI>", encoding="utf-8").read())\n\nCatatan\n-------\n- Skrip tidak menghapus basemap satelit yang sudah ada di project QGIS.\n- Setiap eksekusi disimpan pada folder run baru agar hasil lama tidak tertimpa.\n===============================================================================\n"""\n\nfrom __future__ import annotations\n\nimport csv\nimport math\nfrom datetime import datetime\nfrom pathlib import Path\n\n\n# =============================================================================\n# CONFIG\n# =============================================================================\n\nSELAT = "alas"\nCRS_AUTHID = "EPSG:4326"\n\n# Raster IDW halus yang sudah berhasil dibuat melalui pipeline cepat.\nSOURCE_RASTER_DIR = Path(\n    r"__QGIS_EXPORT_DIR__\\peta_qgis_final_cepat\\raster"\n)\n\n# Polygon sel aktif Delft3D yang sebelumnya sudah berhasil dibuat.\nPOLYGON_GPKG = Path(\n    r"__QGIS_EXPORT_DIR__\\peta_polygon_grid_aktif\\alas_grid_aktif.gpkg"\n)\nPOLYGON_LAYER_NAME = "alas_grid_aktif"\n\n# CSV titik dominan yang sudah memiliki koordinat geografis.\nDOMINANT_CSV = Path(\n    r"__QGIS_EXPORT_DIR__\\alas_titik_dominan.csv"\n)\n\n# Folder output. Setiap eksekusi membuat folder run baru.\nOUTPUT_ROOT = Path(\n    r"__QGIS_EXPORT_DIR__\\peta_raster_halus_mask_final"\n)\nRUN_ID = datetime.now().strftime("run_%Y%m%d_%H%M%S")\nOUTPUT_DIR = OUTPUT_ROOT / RUN_ID\nOUTPUT_RASTER_DIR = OUTPUT_DIR / "raster_clipped"\nPROJECT_FILE = OUTPUT_DIR / "alas_raster_halus_mask_final.qgz"\n\nGROUP_NAME = "SELAT ALAS — RASTER HALUS MASK FINAL"\nNODATA_VALUE = -9999.0\nRASTER_OPACITY = 0.76\n\n# Legenda tetap untuk seluruh peta kecepatan. Maksimum visual 1,50 m/s.\n# Nilai > 1,50 m/s tidak dihapus; warnanya mengikuti kelas tertinggi.\nSPEED_STOPS = [\n    (0.00, "#313695", "0,00"),\n    (0.40, "#74add1", "0,40"),\n    (0.75, "#ffffbf", "0,75"),\n    (1.00, "#fdae61", "1,00"),\n    (1.25, "#f46d43", "1,25"),\n    (1.50, "#a50026", "≥ 1,50"),\n]\n\nPROBABILITY_STOPS = [\n    (0.0, "#313695", "0"),\n    (20.0, "#74add1", "20"),\n    (40.0, "#ffffbf", "40"),\n    (60.0, "#fdae61", "60"),\n    (80.0, "#f46d43", "80"),\n    (100.0, "#a50026", "100"),\n]\n\nRASTER_CONFIG = {\n    "speed_mean": {\n        "title": "01 Kecepatan arus rata-rata [m/s] — MASK FINAL",\n        "kind": "speed",\n        "visible": True,\n    },\n    "speed_spring": {\n        "title": "02 Kecepatan arus spring tide [m/s] — MASK FINAL",\n        "kind": "speed",\n        "visible": False,\n    },\n    "speed_neap": {\n        "title": "03 Kecepatan arus neap tide [m/s] — MASK FINAL",\n        "kind": "speed",\n        "visible": False,\n    },\n    "speed_p90": {\n        "title": "04 Kecepatan arus P90 [m/s] — MASK FINAL",\n        "kind": "speed",\n        "visible": False,\n    },\n    "power_mean": {\n        "title": "05 Densitas daya arus rata-rata [W/m²] — MASK FINAL",\n        "kind": "power",\n        "visible": False,\n    },\n    "prob_v075_pct": {\n        "title": "06 Probabilitas V ≥ 0,75 m/s [%] — MASK FINAL",\n        "kind": "probability",\n        "visible": False,\n    },\n    "prob_v10_pct": {\n        "title": "07 Probabilitas V ≥ 1,00 m/s [%] — MASK FINAL",\n        "kind": "probability",\n        "visible": False,\n    },\n}\n\n\n# =============================================================================\n# UTILITAS\n# =============================================================================\n\n\ndef section(title: str) -> None:\n    print("\\n" + "=" * 78)\n    print(f"  {title}")\n    print("=" * 78)\n\n\ndef info(message: str) -> None:\n    print(f"  [OK] {message}")\n\n\ndef warning(message: str) -> None:\n    print(f"  [PERINGATAN] {message}")\n\n\ndef fail(message: str) -> None:\n    raise RuntimeError(message)\n\n\ndef require_file(path: Path, label: str) -> None:\n    if not path.exists():\n        fail(f"{label} tidak ditemukan: {path}")\n    info(f"{label}: {path}")\n\n\ndef remove_existing_group(project, root, group_name: str) -> None:\n    """Hapus layer dan group hasil eksekusi sebelumnya dari project aktif."""\n    existing = root.findGroup(group_name)\n    if existing is None:\n        return\n\n    def collect_layer_ids(node):\n        ids = []\n        for child in node.children():\n            if hasattr(child, "layerId"):\n                ids.append(child.layerId())\n            elif hasattr(child, "children"):\n                ids.extend(collect_layer_ids(child))\n        return ids\n\n    layer_ids = collect_layer_ids(existing)\n    root.removeChildNode(existing)\n    for layer_id in layer_ids:\n        if project.mapLayer(layer_id) is not None:\n            project.removeMapLayer(layer_id)\n\n\ndef source_raster_path(field: str) -> Path:\n    return SOURCE_RASTER_DIR / f"{SELAT}_{field}.tif"\n\n\ndef clipped_raster_path(field: str) -> Path:\n    return OUTPUT_RASTER_DIR / f"{SELAT}_{field}_mask_final.tif"\n\n\n# =============================================================================\n# PEMOTONGAN RASTER DENGAN POLYGON GRID AKTIF\n# =============================================================================\n\n\ndef clip_raster_with_active_grid(source: Path, output: Path) -> None:\n    """Potong raster memakai seluruh polygon sel aktif sebagai cutline GDAL."""\n    from osgeo import gdal\n\n    options = gdal.WarpOptions(\n        format="GTiff",\n        cutlineDSName=str(POLYGON_GPKG),\n        cutlineLayer=POLYGON_LAYER_NAME,\n        cropToCutline=True,\n        dstNodata=NODATA_VALUE,\n        multithread=True,\n        creationOptions=[\n            "COMPRESS=DEFLATE",\n            "TILED=YES",\n            "BIGTIFF=IF_SAFER",\n        ],\n        warpOptions=["NUM_THREADS=ALL_CPUS"],\n    )\n\n    dataset = gdal.Warp(str(output), str(source), options=options)\n    if dataset is None:\n        fail(f"GDAL Warp gagal memotong raster: {source}")\n    dataset.FlushCache()\n    dataset = None\n\n\n# =============================================================================\n# SIMBOLOGI QGIS\n# =============================================================================\n\n\ndef raster_min_max(layer) -> tuple[float, float]:\n    from qgis.core import QgsRasterBandStats\n\n    stats = layer.dataProvider().bandStatistics(1, QgsRasterBandStats.All)\n    minimum = float(stats.minimumValue)\n    maximum = float(stats.maximumValue)\n    if not math.isfinite(minimum) or not math.isfinite(maximum):\n        return 0.0, 1.0\n    if maximum <= minimum:\n        maximum = minimum + 1.0\n    return minimum, maximum\n\n\ndef style_raster(layer, kind: str) -> None:\n    from qgis.PyQt.QtGui import QColor\n    from qgis.core import (\n        QgsColorRampShader,\n        QgsRasterShader,\n        QgsSingleBandPseudoColorRenderer,\n    )\n\n    shader_function = QgsColorRampShader()\n    shader_function.setColorRampType(QgsColorRampShader.Interpolated)\n    shader_function.setClip(False)\n\n    if kind == "speed":\n        stops = SPEED_STOPS\n        minimum = 0.0\n        maximum = 1.5\n    elif kind == "probability":\n        stops = PROBABILITY_STOPS\n        minimum = 0.0\n        maximum = 100.0\n    else:\n        raw_min, raw_max = raster_min_max(layer)\n        minimum = max(0.0, raw_min)\n        maximum = raw_max\n        if maximum <= minimum:\n            maximum = minimum + 1.0\n        # Densitas daya memakai gradasi yang sama, tetapi skala aktual raster.\n        steps = 6\n        colors = ["#313695", "#74add1", "#ffffbf", "#fdae61", "#f46d43", "#a50026"]\n        stops = []\n        for index, color in enumerate(colors):\n            value = minimum + (maximum - minimum) * index / (steps - 1)\n            stops.append((value, color, f"{value:.0f}"))\n\n    items = []\n    for value, color_hex, label in stops:\n        items.append(QgsColorRampShader.ColorRampItem(float(value), QColor(color_hex), label))\n\n    shader_function.setColorRampItemList(items)\n    raster_shader = QgsRasterShader()\n    raster_shader.setRasterShaderFunction(shader_function)\n\n    renderer = QgsSingleBandPseudoColorRenderer(layer.dataProvider(), 1, raster_shader)\n    renderer.setClassificationMin(float(minimum))\n    renderer.setClassificationMax(float(maximum))\n    layer.setRenderer(renderer)\n    layer.setOpacity(RASTER_OPACITY)\n    layer.triggerRepaint()\n\n\ndef add_dominant_point(project, group):\n    from qgis.PyQt.QtGui import QColor\n    from qgis.core import (\n        QgsFeature,\n        QgsField,\n        QgsGeometry,\n        QgsMarkerSymbol,\n        QgsPalLayerSettings,\n        QgsPointXY,\n        QgsProject,\n        QgsTextBufferSettings,\n        QgsTextFormat,\n        QgsVectorLayer,\n        QgsVectorLayerSimpleLabeling,\n    )\n    from qgis.PyQt.QtCore import QVariant\n\n    if not DOMINANT_CSV.exists():\n        warning(f"CSV titik dominan tidak ditemukan: {DOMINANT_CSV}")\n        return None\n\n    with DOMINANT_CSV.open("r", encoding="utf-8-sig", newline="") as handle:\n        reader = csv.DictReader(handle)\n        row = next(reader, None)\n\n    if not row:\n        warning("CSV titik dominan kosong.")\n        return None\n\n    def get_number(*keys):\n        for key in keys:\n            if key in row and row[key] not in (None, ""):\n                try:\n                    return float(row[key])\n                except ValueError:\n                    pass\n        return None\n\n    x = get_number("x", "lon", "longitude")\n    y = get_number("y", "lat", "latitude")\n    speed_mean = get_number("speed_mean")\n    power_mean = get_number("power_mean")\n    if x is None or y is None:\n        warning("Koordinat x/y titik dominan tidak ditemukan pada CSV.")\n        return None\n\n    layer = QgsVectorLayer(f"Point?crs={CRS_AUTHID}", "08 Titik dominan", "memory")\n    provider = layer.dataProvider()\n    provider.addAttributes([\n        QgsField("label", QVariant.String),\n        QgsField("speed_mean", QVariant.Double),\n        QgsField("power_mean", QVariant.Double),\n    ])\n    layer.updateFields()\n\n    feature = QgsFeature(layer.fields())\n    feature.setGeometry(QgsGeometry.fromPointXY(QgsPointXY(x, y)))\n    feature["label"] = "Titik dominan"\n    if speed_mean is not None:\n        feature["speed_mean"] = speed_mean\n    if power_mean is not None:\n        feature["power_mean"] = power_mean\n    provider.addFeature(feature)\n    layer.updateExtents()\n\n    symbol = QgsMarkerSymbol.createSimple({\n        "name": "circle",\n        "color": "255,255,0,255",\n        "outline_color": "0,0,0,255",\n        "outline_width": "0.6",\n        "size": "4.0",\n    })\n    layer.renderer().setSymbol(symbol)\n\n    text_format = QgsTextFormat()\n    text_format.setSize(10)\n    text_format.setColor(QColor("black"))\n    buffer = QgsTextBufferSettings()\n    buffer.setEnabled(True)\n    buffer.setSize(1.0)\n    buffer.setColor(QColor("white"))\n    text_format.setBuffer(buffer)\n\n    label_settings = QgsPalLayerSettings()\n    label_settings.enabled = True\n    label_settings.fieldName = "label"\n    label_settings.setFormat(text_format)\n    layer.setLabelsEnabled(True)\n    layer.setLabeling(QgsVectorLayerSimpleLabeling(label_settings))\n\n    project.addMapLayer(layer, False)\n    group.insertLayer(0, layer)\n    return layer\n\n\ndef add_watermark(project, group, reference_layer=None):\n    """Tambahkan watermark identitas pada peta final QGIS."""\n    from qgis.PyQt.QtCore import QVariant\n    from qgis.PyQt.QtGui import QColor\n    from qgis.core import (\n        QgsFeature,\n        QgsField,\n        QgsGeometry,\n        QgsMarkerSymbol,\n        QgsPalLayerSettings,\n        QgsPointXY,\n        QgsTextBufferSettings,\n        QgsTextFormat,\n        QgsVectorLayer,\n        QgsVectorLayerSimpleLabeling,\n    )\n\n    if reference_layer is None or not reference_layer.isValid():\n        warning("Reference raster untuk watermark tidak valid; watermark tidak ditambahkan.")\n        return None\n    extent = reference_layer.extent()\n    width = extent.width()\n    height = extent.height()\n    if width <= 0 or height <= 0:\n        warning("Extent peta tidak valid; watermark tidak ditambahkan.")\n        return None\n\n    # Posisi watermark: pojok kanan bawah, sedikit masuk dari batas peta.\n    x = extent.xMaximum() - 0.025 * width\n    y = extent.yMinimum() + 0.035 * height\n\n    layer = QgsVectorLayer(\n        f"Point?crs={project.crs().authid()}",\n        "WM — Aimar Rendra P.A.",\n        "memory",\n    )\n    provider = layer.dataProvider()\n    provider.addAttributes([QgsField("watermark", QVariant.String)])\n    layer.updateFields()\n\n    feature = QgsFeature(layer.fields())\n    feature.setGeometry(QgsGeometry.fromPointXY(QgsPointXY(x, y)))\n    feature["watermark"] = "© Aimar Rendra P.A. | Teknik Kelautan — Universitas Hasanuddin"\n    provider.addFeature(feature)\n    layer.updateExtents()\n\n    # Simbol titik dibuat transparan; yang terlihat hanya teks watermark.\n    symbol = QgsMarkerSymbol.createSimple({\n        "name": "circle",\n        "color": "255,255,255,0",\n        "outline_color": "255,255,255,0",\n        "size": "0.1",\n    })\n    layer.renderer().setSymbol(symbol)\n\n    text_format = QgsTextFormat()\n    text_format.setSize(8)\n    text_format.setColor(QColor(80, 80, 80, 190))\n    buffer = QgsTextBufferSettings()\n    buffer.setEnabled(True)\n    buffer.setSize(0.8)\n    buffer.setColor(QColor(255, 255, 255, 210))\n    text_format.setBuffer(buffer)\n\n    label_settings = QgsPalLayerSettings()\n    label_settings.enabled = True\n    label_settings.fieldName = "watermark"\n    label_settings.placement = QgsPalLayerSettings.OverPoint\n    label_settings.setFormat(text_format)\n    layer.setLabelsEnabled(True)\n    layer.setLabeling(QgsVectorLayerSimpleLabeling(label_settings))\n\n    project.addMapLayer(layer, False)\n    node = group.addLayer(layer)\n    node.setItemVisibilityChecked(True)\n    info("Watermark ditambahkan: © Aimar Rendra P.A. | Teknik Kelautan — Universitas Hasanuddin")\n    return layer\n\n\n\ndef create_print_layout(project, map_layer):\n    from qgis.core import (\n        QgsPrintLayout,\n        QgsLayoutItemMap,\n        QgsLayoutItemLabel,\n        QgsLayoutItemScaleBar,\n        QgsLayoutPoint,\n        QgsLayoutSize,\n        QgsUnitTypes,\n    )\n    from qgis.PyQt.QtGui import QFont\n\n    layout_manager = project.layoutManager()\n    layout_name = "PETA SELAT ALAS — FINAL"\n\n    old_layout = layout_manager.layoutByName(layout_name)\n    if old_layout is not None:\n        layout_manager.removeLayout(old_layout)\n\n    layout = QgsPrintLayout(project)\n    layout.initializeDefaults()\n    # Kompatibilitas QGIS: beberapa versi QgsLayout tidak menyediakan setName().\n    # Nama layout diatur setelah didaftarkan ke layout manager bila API mendukung.\n\n    page = layout.pageCollection().pages()[0]\n    page.setPageSize(\n        QgsLayoutSize(297, 210, QgsUnitTypes.LayoutMillimeters)\n    )\n\n    title = QgsLayoutItemLabel(layout)\n    title.setText("PETA KECEPATAN ARUS RATA-RATA — SELAT ALAS")\n    title.setFont(QFont("Arial", 16, QFont.Bold))\n    title.attemptMove(\n        QgsLayoutPoint(10, 7, QgsUnitTypes.LayoutMillimeters)\n    )\n    title.attemptResize(\n        QgsLayoutSize(195, 9, QgsUnitTypes.LayoutMillimeters)\n    )\n    layout.addLayoutItem(title)\n\n    subtitle = QgsLayoutItemLabel(layout)\n    subtitle.setText("Simulasi Delft3D • Maret 2026")\n    subtitle.setFont(QFont("Arial", 9))\n    subtitle.attemptMove(\n        QgsLayoutPoint(10, 16, QgsUnitTypes.LayoutMillimeters)\n    )\n    subtitle.attemptResize(\n        QgsLayoutSize(195, 6, QgsUnitTypes.LayoutMillimeters)\n    )\n    layout.addLayoutItem(subtitle)\n\n    map_item = QgsLayoutItemMap(layout)\n    map_item.attemptMove(\n        QgsLayoutPoint(10, 25, QgsUnitTypes.LayoutMillimeters)\n    )\n    map_item.attemptResize(\n        QgsLayoutSize(220, 165, QgsUnitTypes.LayoutMillimeters)\n    )\n    map_item.setFrameEnabled(True)\n    map_item.setExtent(map_layer.extent())\n    layout.addLayoutItem(map_item)\n\n    wm = QgsLayoutItemLabel(layout)\n    wm.setText(\n        "© Aimar Rendra P.A. | Teknik Kelautan — Universitas Hasanuddin"\n    )\n    wm.setFont(QFont("Arial", 8))\n    wm.setOpacity(0.70)\n    wm.attemptMove(\n        QgsLayoutPoint(10, 192, QgsUnitTypes.LayoutMillimeters)\n    )\n    wm.attemptResize(\n        QgsLayoutSize(220, 7, QgsUnitTypes.LayoutMillimeters)\n    )\n    layout.addLayoutItem(wm)\n\n    source = QgsLayoutItemLabel(layout)\n    source.setText(\n        "Sumber: Pemodelan hidrodinamika Delft3D; BATNAS; pengolahan penulis."\n    )\n    source.setFont(QFont("Arial", 7))\n    source.attemptMove(\n        QgsLayoutPoint(10, 198, QgsUnitTypes.LayoutMillimeters)\n    )\n    source.attemptResize(\n        QgsLayoutSize(220, 6, QgsUnitTypes.LayoutMillimeters)\n    )\n    layout.addLayoutItem(source)\n\n    scalebar = QgsLayoutItemScaleBar(layout)\n    scalebar.setStyle("Single Box")\n    scalebar.setLinkedMap(map_item)\n    scalebar.setUnits(QgsUnitTypes.DistanceKilometers)\n    scalebar.setNumberOfSegments(4)\n    scalebar.setNumberOfSegmentsLeft(0)\n    scalebar.setHeight(4)\n    scalebar.setUnitsPerSegment(5)\n    scalebar.attemptMove(\n        QgsLayoutPoint(185, 182, QgsUnitTypes.LayoutMillimeters)\n    )\n    scalebar.attemptResize(\n        QgsLayoutSize(45, 10, QgsUnitTypes.LayoutMillimeters)\n    )\n    layout.addLayoutItem(scalebar)\n\n    layout_manager.addLayout(layout)\n    # QGIS versi lama tidak menyediakan QgsLayout.setName(); jangan panggil method tersebut.\n    info(f"Print Layout dibuat: {layout_name}")\n    return layout\n\n\ndef add_active_grid_outline(project, group):\n    """Tambahkan polygon grid aktif sebagai layer pemeriksaan, tetapi sembunyikan."""\n    from qgis.core import QgsFillSymbol, QgsVectorLayer\n\n    uri = f"{POLYGON_GPKG}|layername={POLYGON_LAYER_NAME}"\n    layer = QgsVectorLayer(uri, "09 Grid aktif Delft3D — pemeriksaan", "ogr")\n    if not layer.isValid():\n        warning("Layer polygon grid aktif tidak dapat dimuat untuk pemeriksaan.")\n        return None\n\n    symbol = QgsFillSymbol.createSimple({\n        "color": "255,255,255,0",\n        "outline_color": "0,0,0,110",\n        "outline_width": "0.1",\n    })\n    layer.renderer().setSymbol(symbol)\n\n    project.addMapLayer(layer, False)\n    node = group.addLayer(layer)\n    node.setItemVisibilityChecked(False)\n    return layer\n\n\n# =============================================================================\n# MAIN\n# =============================================================================\n\n\ndef main() -> None:\n    section("RASTER HALUS + MASK GRID AKTIF — SELAT ALAS")\n\n    require_file(POLYGON_GPKG, "GeoPackage polygon grid aktif")\n    for field in RASTER_CONFIG:\n        require_file(source_raster_path(field), f"Raster sumber {field}")\n\n    OUTPUT_RASTER_DIR.mkdir(parents=True, exist_ok=True)\n    info(f"Folder output: {OUTPUT_DIR}")\n\n    section("MEMOTONG RASTER BERDASARKAN DOMAIN GRID AKTIF")\n    clipped_paths = {}\n    for index, (field, config) in enumerate(RASTER_CONFIG.items(), start=1):\n        source = source_raster_path(field)\n        output = clipped_raster_path(field)\n        info(f"Mulai {index}/{len(RASTER_CONFIG)}: {config[\'title\']}")\n        clip_raster_with_active_grid(source, output)\n        clipped_paths[field] = output\n        info(f"Raster terpotong: {output.name}")\n\n    section("MENAMBAHKAN HASIL KE PROJECT QGIS")\n    try:\n        from qgis.core import QgsProject, QgsRasterLayer\n        from qgis.utils import iface\n    except ImportError:\n        fail("Skrip ini harus dijalankan melalui Python Console QGIS Desktop.")\n\n    project = QgsProject.instance()\n    root = project.layerTreeRoot()\n    remove_existing_group(project, root, GROUP_NAME)\n    group = root.insertGroup(0, GROUP_NAME)\n\n    raster_layers = {}\n    for field, config in RASTER_CONFIG.items():\n        path = clipped_paths[field]\n        layer = QgsRasterLayer(str(path), config["title"], "gdal")\n        if not layer.isValid():\n            fail(f"Raster gagal dimuat ke QGIS: {path}")\n        style_raster(layer, config["kind"])\n        project.addMapLayer(layer, False)\n        node = group.addLayer(layer)\n        node.setItemVisibilityChecked(bool(config["visible"]))\n        raster_layers[field] = layer\n        info(f"Layer dimuat: {config[\'title\']}")\n\n    add_dominant_point(project, group)\n    add_active_grid_outline(project, group)\n    add_watermark(project, group, raster_layers["speed_mean"])\n\n    project.setCrs(raster_layers["speed_mean"].crs())\n    iface.mapCanvas().setExtent(raster_layers["speed_mean"].extent())\n    iface.mapCanvas().refresh()\n\n    layout = create_print_layout(project, raster_layers["speed_mean"])\n\n    project.write(str(PROJECT_FILE))\n\n    try:\n        iface.openLayoutDesigner(layout)\n    except Exception as exc:\n        warning(f"Layout berhasil dibuat, tetapi Layout Designer tidak dapat dibuka otomatis: {exc}")\n\n    section("SELESAI")\n    info(f"Project QGIS: {PROJECT_FILE}")\n    info(f"Folder raster terpotong: {OUTPUT_RASTER_DIR}")\n    info("Empat layer kecepatan memakai legenda seragam 0,00–1,50 m/s.")\n    info("Nilai asli >1,50 m/s tetap tersimpan dan memakai warna kelas tertinggi.")\n    print("\\n  Aktifkan hanya satu raster statistik pada satu waktu.")\n    print("  Letakkan basemap satelit pada posisi paling bawah di panel Layers.\\n")\n\n\nmain()\n'



def _normalize_alas_csv_outputs() -> None:
    """Pastikan file CSV hasil tahap data tersedia dengan nama yang dibaca tahap QGIS.

    Tahap QGIS membaca:
      __QGIS_EXPORT_DIR__\alas_all_stats.csv
      __QGIS_EXPORT_DIR__\alas_titik_dominan.csv

    Beberapa run tahap data bisa tersimpan di folder lain atau dengan prefix berbeda.
    Fungsi ini mencari file tersebut dan menyalinnya ke nama standar, tanpa menghapus file asli.
    """
    import shutil

    expected_dir = QGIS_EXPORT_DIR
    candidate_dirs = [QGIS_EXPORT_DIR]
    expected_dir.mkdir(parents=True, exist_ok=True)

    targets = {
        "all_stats": expected_dir / "alas_all_stats.csv",
        "titik_dominan": expected_dir / "alas_titik_dominan.csv",
    }

    def find_candidate(suffix: str):
        candidates = []
        for folder in candidate_dirs:
            if not folder.exists():
                continue
            # nama standar lebih diprioritaskan
            std = folder / f"alas_{suffix}.csv"
            if std.exists():
                candidates.append(std)
            for p in folder.glob(f"*_{suffix}.csv"):
                if p not in candidates:
                    candidates.append(p)
        # Prioritaskan nama yang mengandung alas dan file berukuran > 0.
        candidates = [p for p in candidates if p.exists() and p.stat().st_size > 0]
        candidates.sort(key=lambda p: ("alas" not in p.name.lower(), len(p.name)))
        return candidates[0] if candidates else None

    print("\n" + "=" * 78)
    print("  PRA-CEK CSV ALAS UNTUK TAHAP QGIS")
    print("=" * 78)

    for suffix, target in targets.items():
        if target.exists() and target.stat().st_size > 0:
            print(f"  [OK] File standar tersedia: {target}")
            continue
        source = find_candidate(suffix)
        if source is None:
            print(f"  [ERROR] Tidak menemukan file *_{suffix}.csv di folder kandidat:")
            for folder in candidate_dirs:
                print(f"        - {folder}")
                if folder.exists():
                    csvs = sorted(folder.glob("*.csv"))
                    for csv_file in csvs[:20]:
                        print(f"          • {csv_file.name}")
            raise RuntimeError(
                f"File alas_{suffix}.csv belum tersedia. Jalankan tahap data atau periksa folder output."
            )
        if source.resolve() != target.resolve():
            shutil.copy2(source, target)
            print(f"  [OK] Disalin: {source} -> {target}")
        else:
            print(f"  [OK] File ditemukan: {target}")


def _section(title: str) -> None:
    print("\n" + "=" * 78)
    print(f"  {title}")
    print("=" * 78)


def _run_stage(stage_name: str, code: str) -> None:
    _section(stage_name)

    # Placeholder path hanya diisi saat runtime; source yang diunggah ke GitHub
    # tidak menyimpan path komputer pribadi.
    export_dir = str(QGIS_EXPORT_DIR)
    model_dir = str(MODEL_DIR)
    code = (
        code
        .replace("__QGIS_EXPORT_DIR__", export_dir)
        .replace("__MODEL_DIR__", model_dir)
    )
    # QGIS Python Console menyediakan variabel iface di session utama.
    # Karena tiap tahap dijalankan pada namespace terpisah, iface harus
    # diteruskan eksplisit agar zoom/refresh canvas tidak error.
    namespace = {
        "__name__": f"_one_run_{stage_name.lower().replace(' ', '_')}",
        "__file__": globals().get("__file__", r"<PATH_KE_SCRIPT_INI>"),
        "iface": globals().get("iface"),
    }
    exec(compile(code, f"<{stage_name}>", "exec"), namespace)
    if "main" not in namespace:
        raise RuntimeError(f"Stage {stage_name} tidak memiliki fungsi main().")
    namespace["main"]()





def _force_speed_legend_015() -> None:
    """Paksa semua raster kecepatan memakai legenda seragam 0–1,5 m/s."""
    try:
        from qgis.PyQt.QtGui import QColor
        from qgis.core import (
            QgsColorRampShader,
            QgsProject,
            QgsRasterLayer,
            QgsRasterShader,
            QgsSingleBandPseudoColorRenderer,
        )
    except Exception as exc:
        print(f"  [PERINGATAN] Gagal memuat API QGIS untuk koreksi legenda: {exc}")
        return

    speed_stops = [
        (0.00, "#313695", "0,00"),
        (0.40, "#74add1", "0,40"),
        (0.75, "#ffffbf", "0,75"),
        (1.00, "#fdae61", "1,00"),
        (1.25, "#f46d43", "1,25"),
        (1.50, "#a50026", "≥ 1,50"),
    ]

    def is_speed_layer(name: str) -> bool:
        lower = name.lower()
        if "densitas" in lower or "probabilitas" in lower or "power" in lower:
            return False
        return (
            "kecepatan arus" in lower
            or "speed_mean" in lower
            or "speed_spring" in lower
            or "speed_neap" in lower
            or "speed_p90" in lower
        )

    count = 0
    for layer in QgsProject.instance().mapLayers().values():
        if not isinstance(layer, QgsRasterLayer):
            continue
        if not is_speed_layer(layer.name()):
            continue

        shader_function = QgsColorRampShader()
        shader_function.setColorRampType(QgsColorRampShader.Interpolated)
        shader_function.setClip(False)
        if hasattr(shader_function, "setMinimumValue"):
            shader_function.setMinimumValue(0.0)
        if hasattr(shader_function, "setMaximumValue"):
            shader_function.setMaximumValue(1.5)
        shader_function.setColorRampItemList([
            QgsColorRampShader.ColorRampItem(float(value), QColor(color), label)
            for value, color, label in speed_stops
        ])

        raster_shader = QgsRasterShader()
        raster_shader.setRasterShaderFunction(shader_function)
        renderer = QgsSingleBandPseudoColorRenderer(layer.dataProvider(), 1, raster_shader)
        renderer.setClassificationMin(0.0)
        renderer.setClassificationMax(1.5)
        layer.setRenderer(renderer)
        layer.setOpacity(0.76)
        layer.triggerRepaint()
        count += 1

    print(f"  [OK] Legenda 0–1,5 m/s dipaksa ulang pada {count} raster kecepatan.")

