    if not QGIS_EXPORT_DIR.exists():
        raise FileNotFoundError(f"QGIS_EXPORT_DIR tidak ditemukan: {QGIS_EXPORT_DIR}")
    if not MODEL_DIR.exists():
        raise FileNotFoundError(f"MODEL_DIR tidak ditemukan: {MODEL_DIR}")
    print("  Tahap yang akan dijalankan:")
