    print("  2. Polygon grid aktif sebagai mask")
    print("  3. Raster halus final yang dipotong mengikuti domain model")
    print("\n  Jangan tutup QGIS sampai semua tahap selesai.")

    _normalize_alas_csv_outputs()

    _run_stage("TAHAP 1/3 — RASTER HALUS AWAL", FAST_STAGE_CODE)
    _run_stage("TAHAP 2/3 — POLYGON GRID AKTIF", POLYGON_STAGE_CODE)
    _run_stage("TAHAP 3/3 — RASTER HALUS MASK FINAL", MASK_STAGE_CODE)
